import React from 'react';

/**
 * TradePlanCard — Displays a structured trade plan generated by COMPASS agent.
 *
 * Adheres to F.R.I.D.A.Y. design tokens:
 * - Pure Cyber-HUD aesthetic (dark glassmorphism, cyan/amber/emerald highlights)
 * - Honest disclosures: missing data displayed as "—", never invented
 * - Clear risk parameters (Entry, Stop Loss, Target 1/2, R:R ratio, Position Size)
 */
export default function TradePlanCard({ plan, onSendToChart, onRiskCheck, onExecuteClick }) {
  if (!plan) {
    return (
      <div style={{
        background: 'rgba(15, 23, 42, 0.65)',
        border: '1px dashed rgba(255, 255, 255, 0.15)',
        borderRadius: '6px',
        padding: '24px',
        textAlign: 'center',
        color: 'var(--text-muted)',
        fontFamily: 'var(--font-data)',
        fontSize: '12px'
      }}>
        NO TRADE PLAN SELECTED · ISSUE COMMAND "Plan a swing trade in AAPL" OR SELECT A TEMPLATE
      </div>
    );
  }

  const isLong = (plan.direction || 'long').toLowerCase() === 'long';
  const rrColor = plan.rewardRisk >= 2.0 ? 'var(--neon-green)' : plan.rewardRisk >= 1.5 ? 'var(--neon-amber)' : 'var(--neon-red)';

  return (
    <div style={{
      background: 'rgba(10, 15, 29, 0.85)',
      backdropFilter: 'blur(12px)',
      border: '1px solid rgba(0, 240, 255, 0.25)',
      borderRadius: '8px',
      padding: '16px 20px',
      position: 'relative',
      overflow: 'hidden',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.4), inset 0 0 16px rgba(0, 240, 255, 0.04)'
    }}>
      {/* Top Banner & Badges */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        borderBottom: '1px solid rgba(255, 255, 255, 0.08)',
        paddingBottom: '12px',
        marginBottom: '14px'
      }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{
            fontSize: '18px',
            fontWeight: 800,
            fontFamily: 'var(--font-display)',
            letterSpacing: '1px',
            color: '#ffffff'
          }}>
            {plan.symbol || '—'}
          </span>

          <span style={{
            background: isLong ? 'rgba(34, 197, 94, 0.15)' : 'rgba(239, 68, 68, 0.15)',
            border: `1px solid ${isLong ? 'var(--neon-green)' : 'var(--neon-red)'}`,
            color: isLong ? 'var(--neon-green)' : 'var(--neon-red)',
            fontSize: '10px',
            fontWeight: 700,
            fontFamily: 'var(--font-data)',
            padding: '2px 8px',
            borderRadius: '3px',
            textTransform: 'uppercase',
            letterSpacing: '0.8px'
          }}>
            {isLong ? '▲ LONG' : '▼ SHORT'}
          </span>

          <span style={{
            background: 'rgba(0, 240, 255, 0.1)',
            border: '1px solid rgba(0, 240, 255, 0.3)',
            color: 'var(--neon-cyan)',
            fontSize: '10px',
            fontFamily: 'var(--font-data)',
            padding: '2px 8px',
            borderRadius: '3px',
            textTransform: 'uppercase'
          }}>
            {plan.setupType || 'SWING'}
          </span>

          <span style={{
            background: 'rgba(255, 255, 255, 0.06)',
            color: 'var(--text-muted)',
            fontSize: '10px',
            fontFamily: 'var(--font-data)',
            padding: '2px 6px',
            borderRadius: '3px'
          }}>
            {plan.timeframe || '1D'}
          </span>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <span style={{
            fontSize: '11px',
            color: 'var(--text-muted)',
            fontFamily: 'var(--font-data)'
          }}>
            ID: <span style={{ color: 'var(--neon-cyan)' }}>{plan.planId ? plan.planId.slice(0, 14) : '—'}</span>
          </span>
          <span style={{
            background: plan.status === 'executed' ? 'rgba(34, 197, 94, 0.2)' : 'rgba(234, 179, 8, 0.2)',
            color: plan.status === 'executed' ? 'var(--neon-green)' : 'var(--neon-amber)',
            border: `1px solid ${plan.status === 'executed' ? 'rgba(34, 197, 94, 0.4)' : 'rgba(234, 179, 8, 0.4)'}`,
            fontSize: '9.5px',
            fontWeight: 700,
            padding: '2px 6px',
            borderRadius: '2px',
            textTransform: 'uppercase'
          }}>
            {plan.status || 'PENDING-REVIEW'}
          </span>
        </div>
      </div>

      {/* Thesis & Regime */}
      <div style={{ marginBottom: '14px' }}>
        <div style={{ fontSize: '10px', color: 'var(--text-muted)', textTransform: 'uppercase', marginBottom: '4px', fontFamily: 'var(--font-data)' }}>
          Core Thesis · COMPASS Specialist Agent
        </div>
        <div style={{
          fontSize: '12px',
          color: '#e2e8f0',
          lineHeight: '1.5',
          background: 'rgba(255, 255, 255, 0.02)',
          borderLeft: '2px solid var(--neon-cyan)',
          padding: '6px 10px',
          borderRadius: '0 4px 4px 0'
        }}>
          {plan.thesis || 'No thesis generated.'}
        </div>
        <div style={{ display: 'flex', gap: '16px', marginTop: '6px', fontSize: '10.5px', color: 'var(--text-muted)', fontFamily: 'var(--font-data)' }}>
          <span>Regime: <strong style={{ color: '#ffffff' }}>{plan.marketRegime || 'trending'}</strong></span>
          <span>Entry Type: <strong style={{ color: '#ffffff' }}>{plan.entryType || 'pullback-to-level'}</strong></span>
          <span>Time Stop: <strong style={{ color: '#ffffff' }}>{plan.timeStop || '10 trading days'}</strong></span>
        </div>
      </div>

      {/* Key Numbers Grid (Entry, Stop, Targets, R:R) */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(4, 1fr)',
        gap: '10px',
        background: 'rgba(0, 0, 0, 0.3)',
        border: '1px solid rgba(255, 255, 255, 0.05)',
        borderRadius: '6px',
        padding: '12px',
        marginBottom: '14px'
      }}>
        {/* Entry Price */}
        <div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Entry Trigger
          </div>
          <div style={{ fontSize: '16px', fontWeight: 800, color: 'var(--neon-cyan)', fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {plan.entryPrice ? `$${parseFloat(plan.entryPrice).toFixed(2)}` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            {plan.entryTrigger ? plan.entryTrigger.slice(0, 32) + '...' : 'At confirmation'}
          </div>
        </div>

        {/* Stop Loss */}
        <div>
          <div style={{ fontSize: '9px', color: 'var(--neon-red)', textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Stop Loss (SL)
          </div>
          <div style={{ fontSize: '16px', fontWeight: 800, color: 'var(--neon-red)', fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {plan.stopLoss ? `$${parseFloat(plan.stopLoss).toFixed(2)}` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            Risk: {plan.riskAmount ? `$${parseFloat(plan.riskAmount).toFixed(0)}` : '—'} ({plan.positionSize || '—'} shs)
          </div>
        </div>

        {/* Target 1 */}
        <div>
          <div style={{ fontSize: '9px', color: 'var(--neon-green)', textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Target 1 (T1)
          </div>
          <div style={{ fontSize: '16px', fontWeight: 800, color: 'var(--neon-green)', fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {plan.targets?.[0]?.level ? `$${parseFloat(plan.targets[0].level).toFixed(2)}` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            {plan.targets?.[0]?.label || 'Initial target'}
          </div>
        </div>

        {/* Reward : Risk */}
        <div>
          <div style={{ fontSize: '9px', color: rrColor, textTransform: 'uppercase', fontFamily: 'var(--font-data)' }}>
            Reward : Risk
          </div>
          <div style={{ fontSize: '16px', fontWeight: 800, color: rrColor, fontFamily: 'var(--font-data)', marginTop: '2px' }}>
            {plan.rewardRisk ? `${plan.rewardRisk}R` : '—'}
          </div>
          <div style={{ fontSize: '9px', color: 'var(--text-muted)', marginTop: '2px' }}>
            {plan.rewardRisk >= 1.5 ? '✓ Meets Sentinel min 1.5R' : '⚠ Below 1.5R threshold'}
          </div>
        </div>
      </div>

      {/* Invalidations & Event Risks */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: '1fr 1fr',
        gap: '12px',
        marginBottom: '14px',
        fontSize: '11px'
      }}>
        <div style={{
          background: 'rgba(239, 68, 68, 0.05)',
          border: '1px solid rgba(239, 68, 68, 0.15)',
          borderRadius: '4px',
          padding: '8px 10px'
        }}>
          <div style={{ color: 'var(--neon-red)', fontWeight: 700, fontFamily: 'var(--font-data)', marginBottom: '4px', fontSize: '10px' }}>
            THESIS INVALIDATION
          </div>
          <div style={{ color: '#cbd5e1', lineHeight: '1.4' }}>
            {Array.isArray(plan.invalidations) && plan.invalidations.length > 0
              ? plan.invalidations.slice(0, 2).map((inv, idx) => (
                  <div key={idx}>• {inv}</div>
                ))
              : plan.provesThesisWrong || 'Daily close below stop level.'}
          </div>
        </div>

        <div style={{
          background: 'rgba(234, 179, 8, 0.05)',
          border: '1px solid rgba(234, 179, 8, 0.15)',
          borderRadius: '4px',
          padding: '8px 10px'
        }}>
          <div style={{ color: 'var(--neon-amber)', fontWeight: 700, fontFamily: 'var(--font-data)', marginBottom: '4px', fontSize: '10px' }}>
            KNOWN EVENT RISKS
          </div>
          <div style={{ color: '#cbd5e1', lineHeight: '1.4' }}>
            {Array.isArray(plan.eventRisks) && plan.eventRisks.length > 0
              ? plan.eventRisks.slice(0, 2).map((ev, idx) => (
                  <div key={idx}>• {ev}</div>
                ))
              : 'FOMC calendar & earnings window check.'}
          </div>
        </div>
      </div>

      {/* Action Bar & Disclosures */}
      <div style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        borderTop: '1px solid rgba(255, 255, 255, 0.08)',
        paddingTop: '10px'
      }}>
        <div style={{ fontSize: '9px', color: 'var(--text-muted)', fontFamily: 'var(--font-data)' }}>
          Sources: {(plan.sources || ['finnhub:live', 'compass:deterministic']).join(' · ')}
        </div>

        <div style={{ display: 'flex', gap: '8px' }}>
          {onSendToChart && (
            <button
              onClick={() => onSendToChart(plan)}
              style={{
                background: 'rgba(0, 240, 255, 0.1)',
                border: '1px solid rgba(0, 240, 255, 0.4)',
                color: 'var(--neon-cyan)',
                fontFamily: 'var(--font-data)',
                fontSize: '10px',
                padding: '5px 10px',
                borderRadius: '3px',
                cursor: 'pointer',
                letterSpacing: '0.5px'
              }}
            >
              📊 CHART LEVELS
            </button>
          )}

          {onRiskCheck && (
            <button
              onClick={() => onRiskCheck(plan)}
              style={{
                background: 'rgba(234, 179, 8, 0.1)',
                border: '1px solid rgba(234, 179, 8, 0.4)',
                color: 'var(--neon-amber)',
                fontFamily: 'var(--font-data)',
                fontSize: '10px',
                padding: '5px 10px',
                borderRadius: '3px',
                cursor: 'pointer',
                letterSpacing: '0.5px'
              }}
            >
              🛡️ SENTINEL RISK CHECK
            </button>
          )}

          {onExecuteClick && (
            <button
              onClick={() => onExecuteClick(plan)}
              style={{
                background: 'rgba(34, 197, 94, 0.15)',
                border: '1px solid var(--neon-green)',
                color: 'var(--neon-green)',
                fontFamily: 'var(--font-data)',
                fontSize: '10px',
                fontWeight: 700,
                padding: '5px 12px',
                borderRadius: '3px',
                cursor: 'pointer',
                letterSpacing: '0.5px'
              }}
            >
              ⚡ PROCEED TO WORKFLOW
            </button>
          )}
        </div>
      </div>
    </div>
  );
}
